-- Full shared content seed for the Walthamforest Revision Website.
-- This seeds the shared curriculum/content tables only.
-- User-specific tables such as profiles, onboarding, progress, activity, diagnostics, and coaching memory are intentionally excluded.

begin;
-- curriculum_sources (69 rows)
on conflict (id) do update set
  title = excluded.title,
  kind = excluded.kind,
  classification = excluded.classification,
  file_path = excluded.file_path,
  year = excluded.year,
  duplicate_of_id = excluded.duplicate_of_id,
  caution = excluded.caution,
  notes = excluded.notes;

-- curriculum_topics (9 rows)
on conflict (id) do update set
  label = excluded.label,
  short_label = excluded.short_label,
  icon = excluded.icon,
  description = excluded.description,
  mapping_note = excluded.mapping_note,
  sort_order = excluded.sort_order;

-- curriculum_subtopics (33 rows)
on conflict (id) do update set
  topic_id = excluded.topic_id,
  label = excluded.label,
  summary = excluded.summary,
  keywords = excluded.keywords,
  sort_order = excluded.sort_order;

-- curriculum_points (32 rows)
on conflict (id) do update set
  code = excluded.code,
  title = excluded.title,
  summary = excluded.summary,
  source_id = excluded.source_id,
  parent_point_id = excluded.parent_point_id,
  depth = excluded.depth,
  sort_order = excluded.sort_order;

-- curriculum_topic_points (44 rows)
on conflict (topic_id, point_id) do update set
  sort_order = excluded.sort_order;

-- curriculum_terms (30 rows)
on conflict (id) do update set
  term = excluded.term,
  definition = excluded.definition,
  aliases = excluded.aliases,
  legacy_topic_ids = excluded.legacy_topic_ids;

-- curriculum_point_terms (58 rows)
on conflict (point_id, term_id) do nothing;

-- curriculum_materials (38 rows)
on conflict (id) do update set
  source_id = excluded.source_id,
  title = excluded.title,
  kind = excluded.kind,
  display_type = excluded.display_type,
  file_path = excluded.file_path,
  summary = excluded.summary,
  year = excluded.year,
  tags = excluded.tags,
  legacy_topic_ids = excluded.legacy_topic_ids,
  estimated_minutes = excluded.estimated_minutes;

-- curriculum_point_materials (245 rows)
on conflict (point_id, material_id) do nothing;

-- curriculum_questions (301 rows)
on conflict (id) do update set
  source_id = excluded.source_id,
  title = excluded.title,
  source_label = excluded.source_label,
  year = excluded.year,
  paper = excluded.paper,
  question_type = excluded.question_type,
  marks = excluded.marks,
  summary = excluded.summary,
  expectation = excluded.expectation,
  practice_prompt = excluded.practice_prompt,
  legacy_topic_ids = excluded.legacy_topic_ids;

-- curriculum_question_points (496 rows)
on conflict (question_id, point_id) do nothing;

-- curriculum_concepts (96 rows)
on conflict (id) do update set
  topic_id = excluded.topic_id,
  subtopic_id = excluded.subtopic_id,
  question_schema_id = excluded.question_schema_id,
  label = excluded.label,
  weight = excluded.weight,
  feedback = excluded.feedback,
  required_groups = excluded.required_groups;

-- curriculum_misconceptions (32 rows)
on conflict (id) do update set
  topic_id = excluded.topic_id,
  subtopic_id = excluded.subtopic_id,
  question_schema_id = excluded.question_schema_id,
  label = excluded.label,
  explanation = excluded.explanation,
  penalty = excluded.penalty,
  signal_groups = excluded.signal_groups;

-- curriculum_practice_prompts (132 rows)
on conflict (id) do update set
  point_id = excluded.point_id,
  subtopic_id = excluded.subtopic_id,
  prompt_source = excluded.prompt_source,
  prompt_text = excluded.prompt_text,
  sort_order = excluded.sort_order;
commit;
