insert into public.curriculum_sources (id, title, kind, classification, file_path, year, duplicate_of_id, caution, notes)
values
  ('dsd-spec-2025', 'T Level Technical Qualification in Digital Software Development Specification', 'specification', 'primary', 'docs/raw/spec/digital-dsd-specification.pdf', 2025, null, null, 'Canonical curriculum source for Digital Software Development. Content area structure and scope should be taken from here first.'),
  ('dsd-spec-2025-copy', 'Digital Software Development Specification Copy', 'specification', 'duplicate', 'docs/raw/exams/digital-dsd-specification-1.pdf', 2025, 'dsd-spec-2025', null, 'Duplicate copy of the 2025 Digital Software Development specification kept in the exams folder.'),
  ('pearson-dsd-qualification-page', 'Pearson Qualification Page: Digital Software Development', 'specification', 'primary', 'https://qualifications.pearson.com/en/qualifications/t-levels/digital-software-development.html', 2025, null, null, 'Official qualification landing page for the Pearson T Level in Digital Software Development. Useful for the live qualification overview and official web context alongside the specification PDF.'),
  ('pearson-dsd-qualification-description', 'Pearson Qualification Description PDF', 'specification', 'primary', 'https://qualifications.pearson.com/content/dam/pdf/T%20Levels/Digital%20Software%20Development/Technical%20Qualification/Pearson-TQ-Digital-Software-Development_Qualification-Description.pdf', 2025, null, null, 'Official qualification description PDF covering the programme shape, core component context, occupational specialism expectations, and qualification overview.'),
  ('tlevels-student-dsd-page', 'T Levels Student Page: Digital Software Development', 'specification', 'secondary', 'https://www.tlevels.gov.uk/students/subjects/digital-software-development', 2025, null, null, 'Student-facing overview of the Digital Software Development T Level, including the broad qualification shape, progression context, and high-level route explanation.'),
  ('tlevels-support-dsd-page', 'T Levels Support: Digital Software Development', 'textbook', 'secondary', 'https://support.tlevels.gov.uk/hc/en-gb/articles/13813213896210-Digital-Production-Design-and-Development-now-T-Level-in-Digital-Software-Development', 2025, null, null, 'Official provider-support article explaining the Digital Software Development naming update and linking out to teaching, learning, and support materials.'),
  ('tlevels-update-march-2025', 'T Level Update March 2025', 'textbook', 'secondary', 'https://support.tlevels.gov.uk/hc/en-gb/articles/25130056060434-T-Level-update-March-2025', 2025, null, null, 'Official update article explaining the March 2025 transition messaging and streamlining around the Digital Software Development route.'),
  ('pearson-dsd-course-materials', 'Pearson Course Materials Page: Digital Software Development', 'textbook', 'secondary', 'https://qualifications.pearson.com/en/qualifications/t-levels/digital-software-development.coursematerials.html', 2025, null, null, 'Official course materials page. Useful operationally because it currently indicates that course materials are not yet listed there, which affects where support content must be sourced from.'),
  ('dpdd-core-book-2023', 'Digital Production, Design and Development T Level: Core', 'textbook', 'legacy', 'docs/raw/core-book/Digital Production, Design and Development T Level_ Core.pdf', 2023, null, 'This is aligned to the older Digital Production, Design and Development core structure, not the 2025 DSD occupational specification.', 'Useful for legacy numbered topic detail, terminology, explanations, and practice prompts where it aligns conceptually with the current app topics.'),
  ('paper1-q-and-a', 'Paper 1 Q and A', 'question-bank', 'legacy', 'docs/raw/exams/Paper 1 Q and A.pdf', null, null, 'Use as an enrichment source for practice coverage and common question patterns, not as the canonical curriculum structure.', 'Compiled question bank aligned to older core topics such as variables, validation, decomposition, abstraction, flowcharts, and sorting/searching.'),
  ('curated-paper1-practice', 'Curated Paper 1 Practice Set', 'question-bank', 'secondary', 'internal://curated-paper1-practice', 2026, null, null, 'Internal practice set written in simpler exam language to increase Paper 1 retrieval coverage across requirements, testing, and core terminology.'),
  ('curated-paper2-practice', 'Curated Paper 2 Practice Set', 'question-bank', 'secondary', 'internal://curated-paper2-practice', 2026, null, null, 'Internal scenario-style question set written in clearer language to expand Paper 2 applied practice across UI, deployment, change, APIs, and collaboration.'),
  ('core-paper2-autumn-2022', 'Core Paper 2 Autumn 2022', 'past-paper', 'legacy', 'docs/raw/exams/core-paper-2- autumn-22.pdf', 2022, null, 'Question coverage is valuable, but topic naming and scope must be mapped carefully to the 2025 DSD structure.', 'Older Digital Production, Design and Development paper covering business context, data, digital environments, and security.'),
  ('core-paper2-november-2021', 'Core Paper 2 November 2021', 'past-paper', 'legacy', 'docs/raw/exams/core-paper-2- november 21.pdf', 2021, null, 'Keep as enrichment only because it follows the older DPDD core assessment model.', 'Legacy paper used for exam-style phrasing and topic coverage patterns.'),
  ('paper2-2023', 'Paper 2 2023', 'past-paper', 'legacy', 'docs/raw/exams/Paper 2 2023.pdf', 2023, null, 'Still maps to the older core exam rather than the 2025 DSD occupational content areas.', 'Recent legacy paper with strong usable prompts around UI design, security, change, and virtual environments.'),
  ('mark-scheme-autumn-2022', 'Core Paper 2 Mark Scheme Autumn 2022', 'mark-scheme', 'legacy', 'docs/raw/exams/core-paper-2-mark-scheme-autumn-2022.pdf', 2022, null, 'Mark-scheme concepts should enrich mappings and scoring logic, not override the canonical DSD structure.', 'Useful source for concept targets, accepted answers, and evaluation patterns that can support answer-checking heuristics.'),
  ('mark-scheme-summer-2022', 'Mark Scheme Summer 2022', 'mark-scheme', 'legacy', 'docs/raw/exams/mark scheme - summer 22.pdf', 2022, null, 'Use carefully because the exam belongs to the older core model.', 'Additional legacy mark-scheme coverage for data, business, and security answer expectations.'),
  ('mark-scheme-autumn-2021', 'Paper 2 Mark Scheme Autumn 2021', 'mark-scheme', 'legacy', 'docs/raw/exams/paper 2 mark scheme - autumn 21.pdf', 2021, null, 'Should be used for concept enrichment only.', 'Extra evidence for recurring concept targets and common explanation patterns in legacy paper 2 responses.'),
  ('teach-csv-data-formats-worksheet', 'Data formats worksheet (CSV)', 'textbook', 'secondary', '/sources/3-5-data-format-worksheet.csv', 2025, null, null, 'Snippets for JSON, XML, CSV, plain text, UTF-8 vs ASCII issues — from delivery pack extract.'),
  ('teach-csv-data-formats-answers', 'Data formats answer sheet (CSV)', 'textbook', 'secondary', '/sources/3-5-data-format-answers.csv', 2025, null, null, 'Format type, clues, and real-world use cases aligned to worksheet.'),
  ('teach-csv-wrangling-messy', 'Data wrangling messy dataset (CSV)', 'textbook', 'secondary', '/sources/3-8-data-wrangling-dataset.csv', 2025, null, null, 'Deliberately dirty rows for structure, clean, validate, enrich, output practice.'),
  ('teach-csv-wrangling-answers', 'Data wrangling dataset answers (CSV)', 'textbook', 'secondary', '/sources/3-8-data-wrangling-dataset-answers.csv', 2025, null, null, 'Answer/cleaned comparison for wrangling tasks.'),
