insert into public.curriculum_topics (id, label, short_label, icon, description, mapping_note, sort_order)
values
  ('problem-solving', 'Problem Solving', '1', '🧩', 'Breaking down problems, designing solutions with flowcharts and pseudocode.', 'The current app topic covers older core problem-solving content. It aligns most closely with DSD analysis, design, and test planning rather than a single official content area.', 1),
  ('intro-programming', 'Intro to Programming', '2', '💻', 'Writing, testing, and maintaining code — variables, loops, functions, all of it.', 'Legacy programming theory maps mainly to DSD implementation, UI creation, and testing practice.', 2),
  ('emerging-issues', 'Emerging Issues & Digital Impact', '3', '🌐', 'How digital tech is changing the world — AI, IoT, ethics, and accessibility.', 'Emerging issues remains a legacy core-exam topic, so it is mapped to DSD technology impact, ethics, risk, and change drivers.', 3),
  ('legislation', 'Legislation & Regulatory', '4', '⚖️', 'Laws and rules that govern how we build and use digital systems.', 'Legacy legislation content maps directly to DSD legal, regulatory, ethical, and risk-management coverage.', 4),
  ('business', 'Business Environment', '5', '📋', 'How businesses work, the value of digital, and managing change.', 'Business context overlaps with planning, team roles, methodologies, collaborative delivery, and change management in DSD.', 5),
  ('data', 'Data', '6', '🗄️', 'How data is stored, structured, managed, and used in organisations.', 'Legacy data theory maps most strongly to feedback data collection, database design, and data source integration.', 6),
  ('digital-environments', 'Digital Environments', '7', '🖥️', 'Networks, cloud, VMs, hardware — the systems software runs on.', 'Digital environments maps to target platform decisions, collaborative tooling, implementation environment choices, and deployment methods.', 7),
  ('security', 'Security', '8', '🔒', 'Threats to digital systems and how to defend against them.', 'Security aligns with secure-by-design requirements, risk management, secure implementation, security testing, and maintenance after vulnerabilities appear.', 8),
  ('esp', 'ESP', 'ESP', '📝', 'Synoptic employer-set project work: reading the brief, planning a solution, building evidence, and evaluating the final outcome.', 'ESP is synoptic in the current app, so it maps to planning, design, implementation, testing, and controlled change.', 9)
insert into public.curriculum_subtopics (id, topic_id, label, summary, keywords, sort_order)
values
  ('1.1', 'problem-solving', 'Computational thinking', 'Explain that pattern recognition looks for similarities, trends, or repeated features. Explain that recognised patterns help reuse methods, rules, or known solutions. Link this to faster design, more reliable algorithms, or less wasted effort.', array['decomposition', 'abstraction', 'pattern recognition', 'algorithmic thinking', 'flowchart', 'pseudocode', 'trace table']::text[], 1),
  ('1.2', 'problem-solving', 'Algorithms', 'Explain that flowcharts or pseudocode help plan the logic before coding. Explain that they make sequence, decisions, and repetition easier to check or communicate. Link this to finding errors early, clearer collaboration, or more accurate code.', array['searching', 'sorting', 'efficiency', 'bubble sort', 'linear search', 'binary search', 'merge sort']::text[], 2),
  ('2.1', 'intro-programming', 'Program data', null, array['variables', 'constants', 'data types', 'integer', 'string', 'boolean', 'float', 'casting']::text[], 1),
  ('2.2', 'intro-programming', 'Operators', null, array['arithmetic', 'comparison', 'logical', 'assignment', 'modulus', 'AND', 'OR', 'NOT']::text[], 2),
  ('2.3', 'intro-programming', 'File handling', null, array['read', 'write', 'append', 'CSV', 'text file', 'open', 'close']::text[], 3),
  ('2.4', 'intro-programming', 'Program structure', null, array['sequence', 'selection', 'iteration', 'if', 'else', 'while', 'for', 'loops', 'functions', 'procedures', 'parameters']::text[], 4),
  ('2.5', 'intro-programming', 'Built-in functions', null, array['len', 'range', 'print', 'input', 'type', 'int', 'str', 'round', 'string methods']::text[], 5),
  ('2.6', 'intro-programming', 'Validation and error handling', 'Explain that validation checks whether input is acceptable before it is used. Explain that error handling deals with unexpected problems while the program is running. Link both to robustness, fewer crashes, or better data quality.', array['try', 'except', 'validation', 'range check', 'type check', 'presence check', 'length check', 'error handling']::text[], 6),
  ('2.7', 'intro-programming', 'Maintainable code', null, array['comments', 'naming conventions', 'indentation', 'readability', 'modular', 'documentation']::text[], 7),
  ('2.8', 'intro-programming', 'Testing', null, array['test plan', 'test data', 'normal', 'boundary', 'erroneous', 'unit testing', 'integration testing', 'debugging']::text[], 8),
  ('3.1', 'emerging-issues', 'Moral and ethical issues', 'Explain that services should work for a wide range of users, including people with disabilities or limited access. Explain that inclusive design reduces exclusion and improves fair access. Link this to usability, legal or ethical responsibilities, or wider service reach.', array['ethics', 'privacy', 'surveillance', 'bias', 'accessibility', 'digital divide', 'environmental impact', 'autonomy']::text[], 1),
  ('3.2', 'emerging-issues', 'Emerging trends and technologies', 'Explain one realistic benefit such as automation, monitoring, or real-time data collection. Explain one realistic risk such as security exposure, privacy loss, or unreliable data. Show why organisations need controls or careful implementation.', array['AI', 'machine learning', 'IoT', 'blockchain', 'VR', 'AR', 'automation', 'quantum computing', 'big data']::text[], 2),
  ('4.1', 'legislation', 'Legislation', 'Explain that unauthorised access or unauthorised modification is illegal. Explain that staff must stay within the permissions and systems they are allowed to use. Link this to protecting data, systems, or professional responsibility.', array['GDPR', 'DPA', 'Data Protection Act', 'Computer Misuse Act', 'Copyright', 'Freedom of Information', 'employee monitoring', 'PECR', 'intellectual property']::text[], 1),
  ('4.2', 'legislation', 'Guidelines and codes of conduct', 'Explain that accessibility guidance helps teams design software people can actually use. Explain that professional codes of conduct shape responsible and ethical behaviour. Link this to trust, quality, inclusive practice, or reduced legal and reputational risk.', array['BCS', 'code of conduct', 'professional standards', 'acceptable use', 'whistleblowing', 'professional body']::text[], 2),
  ('5.1', 'business', 'The business environment', null, array['stakeholders', 'organisational structure', 'roles', 'departments', 'hierarchy', 'flat structure']::text[], 1),
  ('5.2', 'business', 'Digital value to business', null, array['digital transformation', 'efficiency', 'customer experience', 'competitive advantage', 'automation', 'data-driven']::text[], 2),
  ('5.3', 'business', 'Technical change management', 'Explain that a rollback or fallback plan gives the team a safe option if the release fails. Explain that it reduces downtime, disruption, or data loss. Link the plan to business continuity, user confidence, or safer change management.', array['change management', 'implementation', 'training', 'migration', 'rollout', 'parallel running', 'phased']::text[], 3),
  ('5.4', 'business', 'Risks in a business context', null, array['risk assessment', 'contingency', 'disaster recovery', 'business continuity', 'downtime', 'vendor lock-in']::text[], 4),
  ('6.1', 'data', 'Data and information in organisations', 'Explain that different audiences need different levels of detail, complexity, or presentation. Explain that the purpose affects which chart, table, dashboard, or report is most suitable. Link this to clarity, accurate interpretation, or better decision-making.', array['data', 'information', 'knowledge', 'primary', 'secondary', 'qualitative', 'quantitative']::text[], 1),
  ('6.2', 'data', 'Data formats', 'Explain that JSON is identified by key-value pairs, braces, or arrays. Explain that XML is identified by tags, elements, or attributes. Link both to structured, self-describing exchange between systems or services.', array['CSV', 'JSON', 'XML', 'binary', 'text', 'data interchange', 'file format']::text[], 2),
  ('6.3', 'data', 'Data systems', 'Explain that a data warehouse usually stores structured, prepared data for reporting. Explain that a data lake can hold raw or varied data types at scale. Link this to organisations using both for flexible storage plus analysis-ready reporting.', array['database', 'SQL', 'relational', 'table', 'record', 'field', 'primary key', 'foreign key', 'normalisation', 'query']::text[], 3),
  ('6.4', 'data', 'Data management', 'Explain that raw data is often messy, incomplete, or inconsistent. Explain what the wrangling stages do to make data usable. Link this to more reliable analysis, reporting, or decision-making.', array['backup', 'archive', 'retention', 'disposal', 'integrity', 'redundancy', 'data lifecycle']::text[], 4),
  ('7.1', 'digital-environments', 'Physical environments', null, array['hardware', 'CPU', 'RAM', 'storage', 'server', 'workstation', 'peripheral', 'motherboard']::text[], 1),
  ('7.2', 'digital-environments', 'Networks', null, array['LAN', 'WAN', 'TCP/IP', 'protocol', 'router', 'switch', 'bandwidth', 'topology', 'DNS', 'DHCP', 'firewall']::text[], 2),
  ('7.3', 'digital-environments', 'Virtual environments', null, array['virtual machine', 'hypervisor', 'container', 'sandbox', 'emulation', 'snapshot']::text[], 3),
  ('7.4', 'digital-environments', 'Cloud environments', 'Explain that virtualization allows multiple isolated systems to share hardware efficiently. Explain that cloud scalability allows resources to expand or shrink with demand. Link each benefit to cost, flexibility, testing, or performance.', array['IaaS', 'PaaS', 'SaaS', 'public cloud', 'private cloud', 'hybrid cloud', 'scalability', 'AWS', 'Azure']::text[], 4),
  ('7.5', 'digital-environments', 'Resilience of environment', 'Explain that load balancing spreads work or traffic across more than one server or service. Explain that failover keeps the service running if one part fails. Link both to uptime, performance, or reduced single points of failure.', array['redundancy', 'failover', 'load balancing', 'disaster recovery', 'uptime', 'SLA', 'RAID']::text[], 5),
  ('8.1', 'security', 'Security risks', 'Explain that phishing manipulates users into clicking, revealing details, or trusting a fake message. Explain why this is a human or social-engineering threat. Explain one realistic mitigation such as training, MFA, filtering, or reporting processes.', array['malware', 'phishing', 'social engineering', 'brute force', 'SQL injection', 'DDoS', 'ransomware', 'insider threat', 'zero-day']::text[], 1),
  ('8.2', 'security', 'Threat mitigation', 'Explain that one control can fail, be bypassed, or be misused. Explain that layered controls combine different protections such as prevention, detection, and recovery. Link this to defence in depth, resilience, or reduced overall risk.', array['encryption', 'firewall', 'antivirus', 'authentication', 'two-factor', 'access control', 'penetration testing', 'patching', 'backup']::text[], 2),
  ('esp.1', 'esp', 'Brief analysis', null, array['brief', 'requirements', 'client needs', 'constraints', 'scope', 'acceptance criteria']::text[], 1),
  ('esp.2', 'esp', 'Planning and design', null, array['planning', 'wireframe', 'algorithm', 'flowchart', 'prototype', 'design decisions']::text[], 2),
  ('esp.3', 'esp', 'Implementation evidence', null, array['implementation', 'code evidence', 'database', 'testing evidence', 'screenshots', 'iteration']::text[], 3),
  ('esp.4', 'esp', 'Evaluation and justification', null, array['evaluation', 'justification', 'reflection', 'improvements', 'user feedback', 'success criteria']::text[], 4)
insert into public.curriculum_points (id, code, title, summary, source_id, parent_point_id, depth, sort_order)
values
  ('dsd-ca1', '1', 'Analyse a problem and define requirements aligned to user needs', 'The official starting point for DSD 2025: software lifecycle thinking, requirements, team roles, methodologies, and early planning decisions.', 'dsd-spec-2025', null, 1, 1),
  ('dsd-ca2', '2', 'Apply ethical principles and manage risks in line with legal and regulatory requirements', 'The official legal, ethical, and risk-management strand for DSD 2025, covering standards, compliance, privacy, and mitigation.', 'dsd-spec-2025', null, 1, 2),
  ('dsd-ca3', '3', 'Discover, evaluate, and apply reliable sources of knowledge', 'The evidence and research strand: how developers find trustworthy information and collect qualitative and quantitative feedback.', 'dsd-spec-2025', null, 1, 3),
  ('dsd-ca4', '4', 'Design', 'The core design strand for DSD 2025: design approaches, platform selection, UX/UI, data design, and architecture decisions.', 'dsd-spec-2025', null, 1, 4),
  ('dsd-ca5', '5', 'Create solutions in a social and collaborative environment', 'The teamwork and collaboration strand: why teams collaborate, which tools they use, and when solo work is more appropriate.', 'dsd-spec-2025', null, 1, 5),
  ('dsd-ca6', '6', 'Implement a solution using at least two appropriate languages', 'The implementation strand: selecting languages, building front and back ends, connecting data, shaping UI, and deploying working software.', 'dsd-spec-2025', null, 1, 6),
  ('dsd-ca7', '7', 'Testing a software solution', 'The official testing strand for DSD 2025, spanning test types, testing techniques, security checks, and structured test data.', 'dsd-spec-2025', null, 1, 7),
  ('dsd-ca8', '8', 'Change, maintain, and support software', 'The maintenance strand: why software changes over time and how teams should control, communicate, and test those changes.', 'dsd-spec-2025', null, 1, 8),
  ('dsd-1.1', '1.1', 'Apply software development lifecycle stages to digital projects', 'Understand the full lifecycle from research and planning through design, development, testing, deployment, and maintenance, then apply the right stage activities to a project brief.', 'dsd-spec-2025', 'dsd-ca1', 2, 101),
  ('dsd-1.2', '1.2', 'Understand digital team roles and responsibilities', 'Know how product owners, scrum masters, technical leads, project managers, analysts, designers, developers, operations, security, and testers contribute across the lifecycle.', 'dsd-spec-2025', 'dsd-ca1', 2, 102),
  ('dsd-1.3', '1.3', 'Select appropriate project methodologies', 'Compare Agile, Scaled Agile, Waterfall, RAD, Lean, and user-centred design so methodology choices can be justified against project size, speed, documentation, risk, and user involvement.', 'dsd-spec-2025', 'dsd-ca1', 2, 103),
  ('dsd-1.4', '1.4', 'Define functional and non-functional requirements', 'Specify inputs, processing, logic, data, deployment context, accessibility, scalability, security, performance metrics, and user acceptance criteria for a proposed solution.', 'dsd-spec-2025', 'dsd-ca1', 2, 104),
  ('dsd-1.5', '1.5', 'Investigate emerging technologies and their impact', 'Study how AI, IoT, biometrics, robotics, cloud services, data lakes, warehousing, communications changes, and similar technologies affect software development and industry choices.', 'dsd-spec-2025', 'dsd-ca1', 2, 105),
  ('dsd-1.6', '1.6', 'Identify personal training needs during software development', 'Recognise knowledge or skill gaps, then choose realistic ways to close them through coaching, self-study, on-the-job learning, forums, or structured training.', 'dsd-spec-2025', 'dsd-ca1', 2, 106),
  ('dsd-2.1', '2.1', 'Investigate legal, regulatory, and ethical requirements', 'Apply software-relevant legal and regulatory requirements such as intellectual property, consumer protection, privacy, copyright, equality, licensing, and development standards.', 'dsd-spec-2025', 'dsd-ca2', 2, 201),
  ('dsd-2.2', '2.2', 'Identify, assess, and mitigate software development risks', 'Identify risks around security, compatibility, performance, requirements, user engagement, continuity, and compliance, then justify mitigation and contingency decisions.', 'dsd-spec-2025', 'dsd-ca2', 2, 202),
  ('dsd-3.1', '3.1', 'Evaluate the reliability of different sources of knowledge', 'Use search, repositories, wikis, blogs, papers, forums, comments, and peers responsibly by checking reputation, evidence, bias, triangulation, and currency.', 'dsd-spec-2025', 'dsd-ca3', 2, 301),
  ('dsd-3.2', '3.2', 'Select techniques to gather qualitative and quantitative feedback', 'Use interviews, surveys, observation, focus groups, usage data, mentoring, and other techniques to understand how well a software solution performs for users.', 'dsd-spec-2025', 'dsd-ca3', 2, 302),
  ('dsd-4.1', '4.1', 'Understand common software design approaches', 'Select suitable design approaches such as top-down, OOP, data modelling, test-driven development, behaviour-driven development, and functional design within larger methodologies.', 'dsd-spec-2025', 'dsd-ca4', 2, 401),
  ('dsd-4.2', '4.2', 'Select platforms for source code and content management', 'Understand coding, repository, branching, build, test, and deployment platforms, including open-source versus proprietary trade-offs and common workflow models such as gitFlow.', 'dsd-spec-2025', 'dsd-ca4', 2, 402),
  ('dsd-4.3', '4.3', 'Design a software solution', 'Apply UX and UI principles, create program and database designs, choose assets carefully, understand target platforms, and identify data and network integration points.', 'dsd-spec-2025', 'dsd-ca4', 2, 403),
  ('dsd-5.1', '5.1', 'Understand the reasons for using collaborative techniques', 'Use team working, code reviews, pair programming, walkthroughs, and inspections to reduce delivery time, share knowledge, and improve quality when collaboration is justified.', 'dsd-spec-2025', 'dsd-ca5', 2, 501),
  ('dsd-5.2', '5.2', 'Select technologies for collaborative software development', 'Choose communication, documentation, code collaboration, version control, resource management, and IDE tools that support joint delivery work.', 'dsd-spec-2025', 'dsd-ca5', 2, 502),
  ('dsd-6.1', '6.1', 'Select languages, tools, APIs, and pipelines for implementation', 'Use at least two suitable languages and the right modules, APIs, libraries, security features, packaging, and CI/CD pipeline stages to build a usable front-end and back-end solution.', 'dsd-spec-2025', 'dsd-ca6', 2, 601),
  ('dsd-6.2', '6.2', 'Select interface features and UX techniques', 'Choose interface features such as feedback, media, interaction patterns, data visualisation, layout, typography, colour, focus states, and accessibility fit for the target users and devices.', 'dsd-spec-2025', 'dsd-ca6', 2, 602),
  ('dsd-6.3', '6.3', 'Connect code to data sources', 'Work with databases, APIs, JDBC, ODBC, credentials, endpoints, CRUD actions, and other connections so software can read, store, update, and delete data safely.', 'dsd-spec-2025', 'dsd-ca6', 2, 603),
  ('dsd-6.4', '6.4', 'Select deployment methods for a software project', 'Choose suitable deployment methods such as local, server, web, cloud, mobile, containerised, or orchestrated deployment based on context and operational needs.', 'dsd-spec-2025', 'dsd-ca6', 2, 604),
  ('dsd-7.1', '7.1', 'Select and apply functional, non-functional, front-end, and security testing', 'Use the right test type at the right stage, including unit, smoke, integration, system, load, compatibility, browser, vulnerability, static, and dynamic testing.', 'dsd-spec-2025', 'dsd-ca7', 2, 701),
  ('dsd-7.2', '7.2', 'Select and apply testing techniques', 'Choose acceptance, alpha, beta, open-box, closed-box, manual, or automated techniques to show a solution meets its requirements.', 'dsd-spec-2025', 'dsd-ca7', 2, 702),
  ('dsd-7.3', '7.3', 'Select tests and test data', 'Plan valid, invalid, extreme, erroneous, expected, and regression test evidence so functionality can be checked and re-checked after changes.', 'dsd-spec-2025', 'dsd-ca7', 2, 703),
  ('dsd-8.1', '8.1', 'Understand why digital products change over time', 'Recognise how regulation, new technology, competition, user feedback, vulnerabilities, zero-day issues, failures, and business process changes drive maintenance and iterative improvement.', 'dsd-spec-2025', 'dsd-ca8', 2, 801),
  ('dsd-8.2', '8.2', 'Understand the software change management process', 'Identify issues, document changes, communicate with technical and non-technical audiences, schedule updates, regression test, and release software in a controlled way.', 'dsd-spec-2025', 'dsd-ca8', 2, 802)
