insert into public.curriculum_terms (id, term, definition, aliases, legacy_topic_ids)
values
  ('term-sdlc', 'Software development lifecycle', 'A structured sequence of stages used to research, plan, design, build, test, deploy, and maintain software.', array['SDLC']::text[], array['problem-solving', 'business', 'intro-programming']::text[]),
  ('term-acceptance-criteria', 'Acceptance criteria', 'Specific conditions a solution must meet before a user or client can accept it as fit for purpose.', '{}'::text[], array['problem-solving', 'business']::text[]),
  ('term-agile', 'Agile', 'An iterative development approach that delivers value in increments and adapts requirements over time.', '{}'::text[], array['business', 'problem-solving']::text[]),
  ('term-secure-by-design', 'Secure by design', 'Designing a solution so security requirements are built in early rather than patched on later.', '{}'::text[], array['security', 'legislation']::text[]),
  ('term-kpi', 'KPI', 'A measurable indicator used to judge how well a solution is meeting performance or business goals.', array['key performance indicator']::text[], array['business']::text[]),
  ('term-triangulation', 'Triangulation', 'Checking information against multiple sources to improve confidence that it is reliable.', '{}'::text[], array['business', 'data']::text[]),
  ('term-wireframe', 'Wireframe', 'A simplified design representation that shows layout, structure, and user flow before full visual build.', '{}'::text[], array['business', 'intro-programming']::text[]),
  ('term-erd', 'Entity relationship diagram', 'A data-model diagram used to show entities, attributes, and relationships in a database design.', array['ERD']::text[], array['data']::text[]),
  ('term-version-control', 'Version control', 'A system for tracking changes to code and coordinating development work across versions and contributors.', '{}'::text[], array['intro-programming', 'business']::text[]),
  ('term-api', 'API', 'A defined interface that allows software systems to request or exchange data and functionality.', array['application programming interface']::text[], array['data', 'digital-environments', 'intro-programming']::text[]),
  ('term-cicd', 'CI/CD', 'Continuous integration and continuous deployment: a pipeline approach for building, testing, and releasing software changes regularly.', '{}'::text[], array['intro-programming', 'business']::text[]),
  ('term-accessibility', 'Accessibility', 'Designing software so a wide range of users can perceive, navigate, and use it effectively.', '{}'::text[], array['emerging-issues', 'business', 'legislation']::text[]),
  ('term-vulnerability-scanning', 'Vulnerability scanning', 'A security testing activity that checks a system for known weaknesses that could be exploited.', '{}'::text[], array['security']::text[]),
  ('term-regression-testing', 'Regression testing', 'Re-running tests after a change to check that existing functionality still works as expected.', '{}'::text[], array['intro-programming', 'security']::text[]),
  ('term-business-continuity', 'Business continuity', 'Planning and preparation that keeps critical services running when disruption or incidents occur.', '{}'::text[], array['business', 'security']::text[]),
  ('term-zero-day', 'Zero day', 'A newly discovered vulnerability that is exploited before a fix is available.', '{}'::text[], array['security']::text[]),
  ('term-six-vs-big-data', 'Six Vs of big data', 'Common lens for big data: Volume (scale), Velocity (speed), Variety (mixed formats), Veracity (trust/quality), Value (useful insight), Variability (changing patterns over time).', array['6 Vs', 'big data dimensions']::text[], array['data']::text[]),
  ('term-rbac', 'Role-based access control', 'Access decisions based on a user’s role (e.g. analyst, admin): which assets they may read, write, or administer, often shown in a permission matrix.', array['RBAC']::text[], array['data', 'security']::text[]),
  ('term-data-wrangling', 'Data wrangling', 'Preparing raw data through structuring, cleaning, validating, enriching, and outputting consistent datasets ready for analysis or storage.', array['data cleaning pipeline']::text[], array['data']::text[]),
  ('term-mojibake', 'Mojibake', 'Garbled text when bytes are interpreted with the wrong character encoding (e.g. smart quotes or symbols showing as replacement characters).', array['encoding corruption']::text[], array['data']::text[]),
  ('term-pattern-recognition', 'Pattern recognition', 'Identifying similarities, trends, or repeated structures so a known rule or solution can be reused in a new problem.', '{}'::text[], array['problem-solving']::text[]),
  ('term-digital-inclusion', 'Digital inclusion', 'Designing and delivering digital services so people are not excluded by disability, connectivity, cost, language, confidence, or device limitations.', '{}'::text[], array['emerging-issues', 'legislation', 'business']::text[]),
  ('term-data-warehouse', 'Data warehouse', 'A store of structured, prepared, often historical data used for reporting, analysis, and business intelligence.', '{}'::text[], array['data', 'business']::text[]),
  ('term-data-lake', 'Data lake', 'A large store that can hold raw, semi-structured, and unstructured data before it is refined for later analysis.', '{}'::text[], array['data', 'business']::text[]),
  ('term-confidentiality', 'Confidentiality', 'Keeping information hidden from unauthorised people so only approved users can access it.', '{}'::text[], array['security', 'legislation']::text[]),
  ('term-integrity', 'Integrity', 'Keeping data accurate, complete, and protected from improper or unauthorised change.', '{}'::text[], array['security', 'data']::text[]),
  ('term-availability', 'Availability', 'Making sure systems and data are accessible when authorised users need them.', '{}'::text[], array['security', 'digital-environments']::text[]),
  ('term-network-data-model', 'Network data model', 'A data model that represents highly interconnected records and supports many-to-many relationships more naturally than a strict hierarchy.', '{}'::text[], array['data']::text[]),
  ('term-phishing', 'Phishing', 'A social-engineering attack that tricks users into revealing information, opening malicious content, or trusting a fake message or site.', '{}'::text[], array['security']::text[]),
  ('term-defence-in-depth', 'Defence in depth', 'A layered security approach that combines multiple controls so the system is still protected if one measure fails.', '{}'::text[], array['security']::text[])
