insert into public.curriculum_materials (id, source_id, title, kind, display_type, file_path, summary, year, tags, legacy_topic_ids, estimated_minutes)
values
  ('resource-dsd-spec', 'dsd-spec-2025', 'Official DSD 2025 Specification', 'specification', 'notes', 'docs/raw/spec/digital-dsd-specification.pdf', 'Canonical structure for Digital Software Development. Use this for official content area scope, numbered points, and curriculum boundaries.', null, array['official', 'specification', 'curriculum', 'digital software development']::text[], array['problem-solving', 'intro-programming', 'emerging-issues', 'legislation', 'business', 'data', 'digital-environments', 'security']::text[], 20),
  ('resource-dsd-qualification-page', 'pearson-dsd-qualification-page', 'Official Pearson Qualification Page', 'specification', 'notes', 'https://qualifications.pearson.com/en/qualifications/t-levels/digital-software-development.html', 'Live qualification overview page for the Pearson T Level in Digital Software Development. Use this for the current qualification framing, linked official downloads, and route-level context.', null, array['official', 'pearson', 'qualification', 'overview', 't level']::text[], array['problem-solving', 'intro-programming', 'emerging-issues', 'legislation', 'business', 'data', 'digital-environments', 'security']::text[], 8),
