insert into public.curriculum_questions (id, source_id, title, source_label, year, paper, question_type, marks, summary, expectation, practice_prompt, legacy_topic_ids)
values
  ('paper2-2023-q2a-ui-end-users', 'paper2-2023', 'Design the UI around end-user characteristics', 'Paper 2 2023', 2023, 'Paper 2', 'medium-open', 4, 'Explain two ways a user interface for doctors'' surgeries should take the characteristics of the end users into account.', 'The answer should link user characteristics such as age, pace, expertise, accuracy needs, or accessibility to concrete UI choices.', 'Explain two interface choices that would help busy medical staff prescribe medicine accurately.', array['business', 'intro-programming']::text[]),
  ('paper2-2023-q2b-cia-patient-records', 'paper2-2023', 'Apply confidentiality and integrity to patient records', 'Paper 2 2023', 2023, 'Paper 2', 'medium-open', 4, 'Describe how confidentiality and integrity of patient records apply in a new digital system.', 'A strong answer explains what must be protected, who should access it, and how accuracy and unauthorised change are controlled.', 'Explain how confidentiality and integrity should shape a digital patient records system.', array['security', 'legislation']::text[]),
  ('paper2-2023-q3-quality-service', 'paper2-2023', 'Meet user needs and provide quality service', 'Paper 2 2023', 2023, 'Paper 2', 'short-open', 3, 'Explain one way to ensure a digital system provides a quality service that meets user needs.', 'Good answers connect one design or support decision directly to user satisfaction, reliability, usability, or outcome quality.', 'Explain one practical way a team can keep a digital service useful for its users.', array['business']::text[]),
  ('paper2-2023-q4c-firewall', 'paper2-2023', 'Describe how a firewall improves security', 'Paper 2 2023', 2023, 'Paper 2', 'short-open', 3, 'Describe how a firewall is used to improve security in an organisation.', 'The answer should explain traffic filtering or blocking and link that control to risk reduction.', 'Describe how a firewall cuts the risk of unauthorised access or harmful traffic.', array['security', 'digital-environments']::text[]),
  ('paper2-2023-q5-change-drivers', 'paper2-2023', 'Unforeseen factors that trigger change', 'Paper 2 2023', 2023, 'Paper 2', 'medium-open', 4, 'Describe two unforeseen factors that could trigger change in an organisation.', 'Better answers identify a realistic change trigger and explain why it forces the organisation or system to adapt.', 'Describe two unexpected events that could force a software product or organisation to change.', array['business']::text[]),
  ('paper2-2023-q7-data-access-permissions', 'paper2-2023', 'Evaluate the impact of data access permissions', 'Paper 2 2023', 2023, 'Paper 2', 'extended-response', 9, 'Evaluate the impact of data access permissions on an organisation.', 'High-scoring answers balance the benefits of restricting and controlling access against operational costs, efficiency, and user needs.', 'Evaluate how data access permissions can help an organisation and also cause problems.', array['security', 'data', 'business']::text[]),
  ('paper2-2023-q8a-virtual-environments', 'paper2-2023', 'Benefits of virtual environments in development', 'Paper 2 2023', 2023, 'Paper 2', 'medium-open', 4, 'Explain two benefits of using virtual environments to develop a multiplatform game.', 'The answer should focus on emulation, isolation, testing flexibility, or host security and link each point back to development work.', 'Explain two ways virtual environments help a team build software for different platforms.', array['digital-environments', 'security']::text[]),
  ('paper2-2023-q8b-human-error', 'paper2-2023', 'Human error and development time', 'Paper 2 2023', 2023, 'Paper 2', 'medium-open', 4, 'Explain two ways human error could increase the development time of a software project.', 'A strong answer connects the mistake to rework, communication failure, testing delay, or wasted effort.', 'Explain two ways human mistakes can slow down software delivery.', array['business', 'intro-programming']::text[]),
  ('aut22-q2b-remote-working-risks', 'core-paper2-autumn-2022', 'Remote working cyber threats', 'Autumn 2022 Paper 2', 2022, 'Paper 2', 'medium-open', 4, 'Identify and explain security threats that become relevant when staff work remotely.', 'Answers should pair a specific threat with a clear explanation of how it affects systems, users, or data.', 'Explain two cyber threats that become more serious when staff work remotely.', array['security']::text[]),
  ('aut22-q4-virtual-environments', 'core-paper2-autumn-2022', 'Use virtual environments to test safely', 'Autumn 2022 Paper 2', 2022, 'Paper 2', 'medium-open', 4, 'Explain how virtual environments support effective and safe development or testing.', 'Answers should reference isolation, emulation, or security and link them to the scenario.', 'Explain how a virtual environment makes development safer or more flexible.', array['digital-environments', 'security']::text[]),
  ('aut22-q6-business-risk', 'core-paper2-autumn-2022', 'Assess risks to a digital business service', 'Autumn 2022 Paper 2', 2022, 'Paper 2', 'short-open', 3, 'Identify a realistic business risk and explain the impact on the organisation.', 'The answer should name a risk and show the business consequence rather than stopping at a label.', 'Identify one major risk to a digital service and explain its likely business impact.', array['business', 'security']::text[]),
  ('aut22-q7-data-tools', 'core-paper2-autumn-2022', 'Compare data warehouses, lakes, mining, and reporting', 'Autumn 2022 Paper 2', 2022, 'Paper 2', 'extended-response', 9, 'Evaluate different data storage and analysis approaches in terms of structure, storage, processing, and decision support.', 'Higher marks come from comparing the tools directly and weighing trade-offs rather than listing definitions.', 'Evaluate how a data warehouse, a data lake, data mining, and reporting differ.', array['data', 'business']::text[]),
  ('paper1-practice-requirements-attendance-app', 'curated-paper1-practice', 'Separate functional and non-functional requirements', 'Paper 1 practice', null, 'Paper 1', 'short-open', 3, 'State one functional requirement and one non-functional requirement for a school attendance app.', 'Strong answers clearly separate what the system must do from how well, how safely, or how quickly it must do it.', 'State one functional requirement and one non-functional requirement for a school attendance app.', array['problem-solving', 'business', 'security']::text[]),
  ('paper1-practice-test-data-login-field', 'curated-paper1-practice', 'Choose suitable test data for a login field', 'Paper 1 practice', null, 'Paper 1', 'medium-open', 4, 'Describe suitable test data for a login field that accepts 8 to 20 characters.', 'Good answers include valid, invalid, and extreme examples, then explain what result each test should produce.', 'Describe suitable test data for a login field that accepts 8 to 20 characters.', array['intro-programming', 'problem-solving']::text[]),
  ('paper2-practice-accessible-mobile-booking', 'curated-paper2-practice', 'Design an accessible mobile booking interface', 'Paper 2 practice', null, 'Paper 2', 'medium-open', 4, 'Explain two interface choices that would help users book appointments accurately on a mobile device.', 'Strong answers link each design choice to a real user benefit such as readability, reduced mistakes, accessibility, or faster completion.', 'Explain two interface choices that would help users book appointments accurately on a mobile device.', array['business', 'intro-programming']::text[]),
  ('paper2-practice-cloud-deployment-remote-team', 'curated-paper2-practice', 'Evaluate cloud deployment for a distributed team', 'Paper 2 practice', null, 'Paper 2', 'extended-response', 6, 'Evaluate whether cloud deployment is a good choice for a software team working from several locations.', 'Higher-scoring answers balance benefits such as access, scaling, and collaboration against cost, control, dependency, and security concerns before reaching a judgement.', 'Evaluate whether cloud deployment is a good choice for a software team working from several locations.', array['digital-environments', 'business', 'security']::text[]),
  ('paper2-practice-change-control-release', 'curated-paper2-practice', 'Use change control to protect a live release', 'Paper 2 practice', null, 'Paper 2', 'medium-open', 4, 'Explain how change control can reduce problems when a new feature is released to live users.', 'The answer should show that controlled documentation, approval, testing, scheduling, and communication reduce disruption and release risk.', 'Explain how change control can reduce problems when a new feature is released to live users.', array['business', 'security']::text[]),
  ('paper2-practice-api-credentials-errors', 'curated-paper2-practice', 'Protect API credentials and handle failures safely', 'Paper 2 practice', null, 'Paper 2', 'medium-open', 4, 'Explain why an app that uses an external API should protect its credentials and handle errors carefully.', 'Good answers explain how exposed credentials create risk and why graceful error handling protects users, data, or service quality when requests fail.', 'Explain why an app that uses an external API should protect its credentials and handle errors carefully.', array['security', 'data', 'digital-environments']::text[]),
  ('paper2-practice-feedback-methods-service', 'curated-paper2-practice', 'Compare interviews and analytics for service improvement', 'Paper 2 practice', null, 'Paper 2', 'medium-open', 4, 'Compare interviews and usage analytics when improving an online service.', 'Stronger answers compare the type of evidence each method provides, their limits, and when one method is more useful than the other.', 'Compare interviews and usage analytics when improving an online service.', array['business', 'data']::text[]),
  ('paper2-practice-remote-team-tooling', 'curated-paper2-practice', 'Use shared tools in a remote software team', 'Paper 2 practice', null, 'Paper 2', 'medium-open', 4, 'Explain how version control and shared documentation help a remote software team deliver safely.', 'The answer should explain how traceable code changes, shared knowledge, and clearer collaboration reduce mistakes, duplication, or delivery risk.', 'Explain how version control and shared documentation help a remote software team deliver safely.', array['business', 'digital-environments']::text[]),
  ('paper2-practice-risk-review-feature-launch', 'curated-paper2-practice', 'Judge whether a risky feature should be launched', 'Paper 2 practice', null, 'Paper 2', 'extended-response', 6, 'Evaluate whether a high-reward feature should be released when it also introduces significant security and operational risk.', 'High-mark answers weigh business benefit against security, reliability, and reputational risk, then justify a clear decision with mitigation or contingency ideas.', 'Evaluate whether a high-reward feature should be released when it also introduces major security and operational risk.', array['business', 'security']::text[]),
  ('qb-decomposition-abstraction', 'paper1-q-and-a', 'Question bank: decomposition, pattern recognition, and abstraction', 'Paper 1 Q&A', null, 'Paper 1', 'question-bank-section', null, 'Legacy practice bank section covering decomposition, pattern recognition, and abstraction from the older core structure.', 'Useful for short-answer practice on computational thinking terms, examples, and applied problem solving.', 'Explain how decomposition, pattern recognition, and abstraction work together when solving a problem.', array['problem-solving']::text[]),
  ('qb-validation-and-data-types', 'paper1-q-and-a', 'Question bank: data validation and data types', 'Paper 1 Q&A', null, 'Paper 1', 'question-bank-section', null, 'Legacy question-bank coverage for validation, data types, and related programming basics.', 'Good for retrieval practice around correct typing, validation checks, and basic program logic.', 'Explain why data validation and correct data typing matter in a software solution.', array['intro-programming', 'data']::text[]),
  ('teach-pack-q-data-model-scenarios', 'teach-pack-data-models-worksheet', 'Teaching pack: choose a data model for four scenarios', 'Data models worksheet', 2025, null, 'medium-open', null, 'For an org chart, a social follow graph, a product catalogue with suppliers, and many-to-many tasks for employees, choose hierarchical, network, or relational and justify.', 'Each scenario needs a model choice plus at least one reason (cardinality, flexibility, query complexity, or redundancy).', 'Pick hierarchical, network, or relational for each scenario and justify with relationships and query needs.', array['data']::text[]),
  ('teach-pack-q-big-data-v', 'teach-pack-big-data-worksheet', 'Teaching pack: map scenarios to a big-data V', 'Six Vs worksheet', 2025, null, 'short-open', null, 'Identify which of Volume, Velocity, Variety, Veracity, Value, or Variability best fits short scenarios (e.g. CDR scale, live sentiment, faulty sensors).', 'Correct V plus one sentence of reasoning; accept close synonyms if the logic matches.', 'Name the primary V and explain your choice in one or two sentences.', array['data']::text[]),
  ('teach-pack-q-access-matrix', 'teach-pack-access-control-worksheet', 'Teaching pack: justify access levels in a matrix', 'Access control worksheet', 2025, null, 'medium-open', null, 'Assign Read, Write, Admin, or No access for roles (e.g. intern, analyst, IT admin) against assets (customer DB, payroll) and justify least-privilege choices.', 'Answers should reference sensitivity, segregation of duties, and why admin is rarely default for all staff.', 'Complete two cells in the matrix and explain why those access levels follow least privilege.', array['data', 'security']::text[]),
  ('teach-pack-problem-solving-01', 'teach-pack-problem-solving-lesson-plans', 'Lesson plan: compare top-down, bottom-up, and modularisation', 'Problem solving lesson plans', 2025, null, 'question-bank-section', null, 'Problem-solving lesson-plan coverage asking students to solve a problem using top-down, bottom-up, and modularisation approaches.', 'Strong answers compare how each approach breaks up or builds a solution and justify where each method helps.', 'Compare top-down, bottom-up, and modularisation as ways to solve a software problem.', array['problem-solving']::text[]),
  ('teach-pack-problem-solving-02', 'teach-pack-problem-solving-lesson-plans', 'Lesson plan: identify the main features of a problem', 'Problem solving lesson plans', 2025, null, 'question-bank-section', null, 'Pattern-recognition lesson-plan coverage focused on identifying and describing the main features of a problem or process.', 'Good answers isolate the important elements first instead of jumping straight to code or a finished solution.', 'Identify the main features of a problem or process before you start designing a solution.', array['problem-solving']::text[]),
  ('teach-pack-problem-solving-03', 'teach-pack-problem-solving-lesson-plans', 'Lesson plan: identify trends and similarities', 'Problem solving lesson plans', 2025, null, 'question-bank-section', null, 'Pattern-recognition lesson-plan coverage asking students to identify and describe trends and similarities within and between problems.', 'Strong answers spot repeatable features and explain how these patterns can guide a solution.', 'Identify trends and similarities within and between problems, then explain how those patterns help.', array['problem-solving']::text[]),
  ('teach-pack-problem-solving-04', 'teach-pack-problem-solving-lesson-plans', 'Lesson plan: filter out unnecessary detail', 'Problem solving lesson plans', 2025, null, 'question-bank-section', null, 'Abstraction lesson-plan coverage focused on identifying needed information and filtering out unnecessary detail.', 'Good answers explain what information matters to the solution and what can be safely ignored at this stage.', 'Explain how abstraction helps you keep the information that matters and ignore unnecessary detail.', array['problem-solving']::text[]),
  ('teach-pack-problem-solving-05', 'teach-pack-problem-solving-lesson-plans', 'Lesson plan: define inputs, outputs, and processes', 'Problem solving lesson plans', 2025, null, 'question-bank-section', null, 'Abstraction lesson-plan coverage asking students to define inputs, outputs, and the core process of a solution.', 'Strong answers separate the solution into what goes in, what happens, and what comes out.', 'Define the inputs, outputs, and core process for a simple digital solution.', array['problem-solving']::text[]),
  ('teach-pack-problem-solving-06', 'teach-pack-problem-solving-lesson-plans', 'Lesson plan: explain what makes an algorithm valid', 'Problem solving lesson plans', 2025, null, 'question-bank-section', null, 'Algorithms lesson-plan coverage focused on sequences of unambiguous steps used to achieve a specified outcome.', 'Good answers explain that an algorithm is a clear, ordered process and why ambiguity causes errors.', 'Explain why an algorithm must be a clear sequence of unambiguous steps.', array['problem-solving']::text[]),
  ('teach-pack-emerging-01', 'teach-pack-emerging-slides', 'Slides: compare the impact of digital change across groups', 'Emerging issues slides', 2025, null, 'question-bank-section', null, 'Emerging-issues slide coverage asking students to compare whether the same digital issue creates the same challenge for different groups.', 'Strong answers compare the impact on individuals, society, and organisations instead of treating all groups as identical.', 'Compare how one digital issue affects different groups, such as individuals, society, and organisations.', array['emerging-issues']::text[]),
  ('teach-pack-emerging-02', 'teach-pack-emerging-slides', 'Slides: discuss workplace monitoring', 'Emerging issues slides', 2025, null, 'question-bank-section', null, 'Emerging-issues slide coverage asking students to discuss reactions to statements about workplace monitoring and related rights.', 'Good answers balance benefits such as oversight or safety against privacy, trust, and fairness concerns.', 'Discuss the benefits and concerns linked to workplace monitoring in digital organisations.', array['emerging-issues']::text[]),
  ('teach-pack-emerging-03', 'teach-pack-emerging-slides', 'Slides: balance automation with human skills', 'Emerging issues slides', 2025, null, 'question-bank-section', null, 'Emerging-issues slide coverage asking students to suggest how organisations can balance automation with the need for human skills and knowledge.', 'Strong answers weigh efficiency gains against deskilling, oversight, and the continuing need for human judgement.', 'Suggest how an organisation can balance automation with the need for human skills and knowledge.', array['emerging-issues']::text[]),
  ('teach-pack-emerging-04', 'teach-pack-emerging-slides', 'Slides: present a digital change case study', 'Emerging issues slides', 2025, null, 'question-bank-section', null, 'Emerging-issues slide coverage asking students to present a case study showing how a digital change affects individuals, society, or organisations.', 'Good answers describe the change, explain its impact, and keep the response grounded in a realistic case study.', 'Choose one digital change and present a short case study explaining its impact.', array['emerging-issues']::text[]),
  ('teach-pack-legislation-01', 'teach-pack-legislation-slides', 'Slides: explain the principles of the Computer Misuse Act', 'Legislation slides', 2025, null, 'question-bank-section', null, 'Legislation slide coverage asking students to discuss the different features and principles of the Computer Misuse Act.', 'Strong answers explain unauthorised access or modification clearly and connect the law to workplace behaviour.', 'Explain the main principles of the Computer Misuse Act and how they affect staff behaviour.', array['legislation']::text[]),
  ('teach-pack-legislation-02', 'teach-pack-legislation-slides', 'Slides: discuss consequences for misuse', 'Legislation slides', 2025, null, 'question-bank-section', null, 'Legislation slide coverage asking students to discuss what sentence or consequence would be appropriate within the boundaries of the law.', 'Good answers stay within legal context and justify the consequence using seriousness, intent, or harm.', 'Discuss what consequences could be appropriate in a Computer Misuse Act case and justify your view.', array['legislation']::text[]),
  ('teach-pack-legislation-03', 'teach-pack-legislation-slides', 'Slides: explain why industry standards are needed', 'Legislation slides', 2025, null, 'question-bank-section', null, 'Legislation and guidance slide coverage asking students to explain what industry standards are and why they are needed.', 'Strong answers connect standards to quality, consistency, safety, professionalism, or trust.', 'Explain why industry standards are needed in digital work.', array['legislation']::text[]),
  ('teach-pack-legislation-04', 'teach-pack-legislation-slides', 'Slides: create a code of conduct', 'Legislation slides', 2025, null, 'question-bank-section', null, 'Legislation and guidance slide coverage asking students to create a code of conduct that reflects best practice in a digital organisation.', 'Good answers show professional, ethical, and user-focused behaviours that match the chosen organisation or service.', 'Create a short code of conduct for a digital organisation and explain the best-practice principles behind it.', array['legislation']::text[]),
  ('teach-pack-security-01', 'teach-pack-security-slides', 'Slides: identify confidential information', 'Security slides', 2025, null, 'question-bank-section', null, 'Security slide coverage asking students to identify examples of confidential information held by digital organisations.', 'Strong answers name realistic categories of sensitive data and explain why those examples matter.', 'Identify examples of confidential information that a digital organisation might hold.', array['security']::text[]),
  ('teach-pack-security-02', 'teach-pack-security-slides', 'Slides: explain the consequences of a breach', 'Security slides', 2025, null, 'question-bank-section', null, 'Security slide coverage asking students to research or explain the consequences of breaches involving confidential information.', 'Good answers connect the breach to privacy harm, trust, legal exposure, or operational impact.', 'Explain what could happen if an organisation loses control of confidential information.', array['security']::text[]),
  ('teach-pack-security-03', 'teach-pack-security-slides', 'Slides: identify threats and vulnerabilities in a scenario', 'Security slides', 2025, null, 'question-bank-section', null, 'Security slide coverage asking students to read a scenario and identify the threats and vulnerabilities affecting the organisation.', 'Strong answers separate the threat itself from the weakness that makes the attack easier.', 'Read a security scenario and identify the threats and vulnerabilities involved.', array['security']::text[]),
