  ('1.1::decomposition-breakdown', 'problem-solving', '1.1', 'problem-solving-decomposition-abstraction', 'Decomposition into manageable parts', 2, 'that decomposition splits the problem into smaller parts', '[{"anyOf":["decomposition","break down","split up"]},{"anyOf":["smaller parts","smaller tasks","manageable pieces","sub problems"]}]'::jsonb),
  ('1.1::abstraction-focus', 'problem-solving', '1.1', 'problem-solving-decomposition-abstraction', 'Abstraction focuses on relevant detail', 2, 'that abstraction focuses on relevant detail', '[{"anyOf":["abstraction","abstract"]},{"anyOf":["ignore irrelevant detail","remove unnecessary detail","focus on relevant detail"]}]'::jsonb),
  ('1.1::design-benefit', 'problem-solving', '1.1', 'problem-solving-decomposition-abstraction', 'Design or testing becomes easier', 2, 'the benefit to design, testing, or maintenance', '[{"anyOf":["easier to design","easier to test","easier to maintain","more manageable"]}]'::jsonb),
  ('1.2::trace-follows-steps', 'problem-solving', '1.2', 'problem-solving-trace-tables', 'Trace tables follow steps and values in order', 2, 'that a trace table records each step or variable value in sequence', '[{"anyOf":["trace table","trace tables"]},{"anyOf":["step by step","each step","in order","variable values","track values"]}]'::jsonb),
  ('1.2::trace-finds-errors', 'problem-solving', '1.2', 'problem-solving-trace-tables', 'Trace tables help reveal logic errors', 2, 'that trace tables help spot logic mistakes or wrong results', '[{"anyOf":["find errors","spot errors","logic error","mistake","bug","unexpected result","wrong output"]}]'::jsonb),
  ('1.2::trace-supports-testing', 'problem-solving', '1.2', 'problem-solving-trace-tables', 'Trace tables support testing or debugging', 2, 'the testing or debugging benefit', '[{"anyOf":["testing","debugging","check algorithm","check whether it works","verify the algorithm"]}]'::jsonb),
