  ('2.6::iteration-repeats', 'intro-programming', '2.6', 'intro-programming-validation', 'Iteration repeats until valid input is given', 2, 'that iteration repeats the validation', '[{"anyOf":["iteration","loop","repeat"]},{"anyOf":["until valid","until correct","keep asking","repeat input"]}]'::jsonb),
  ('2.6::robustness-benefit', 'intro-programming', '2.6', 'intro-programming-validation', 'Validation prevents invalid data', 2, 'the effect on robustness or data quality', '[{"anyOf":["prevent invalid data","stop bad data","improve robustness","reduce errors"]}]'::jsonb),
  ('2.6::validation-checks-input', 'intro-programming', '2.6', 'intro-programming-validation-error-handling', 'Validation checks input before processing', 2, 'that validation checks whether input is acceptable', '[{"anyOf":["validation","validate","validation check"]},{"anyOf":["check input","acceptable input","correct format","before processing","before use"]}]'::jsonb),
  ('2.6::error-handling-manages-problems', 'intro-programming', '2.6', 'intro-programming-validation-error-handling', 'Error handling deals with unexpected problems', 2, 'that error handling manages unexpected runtime problems', '[{"anyOf":["error handling","exception handling","try except","catch errors"]},{"anyOf":["unexpected problem","runtime problem","stop crash","handle errors"]}]'::jsonb),
  ('2.6::robustness-data-quality', 'intro-programming', '2.6', 'intro-programming-validation-error-handling', 'Together they improve robustness or data quality', 2, 'the combined benefit to robustness or data quality', '[{"anyOf":["robustness","fewer crashes","prevent bad data","data quality","reliable","reduce errors"]}]'::jsonb),
