  ('4.1::third-party-protected', 'legislation', '4.1', 'legislation-copyright-licensing', 'Third-party code and media are protected by rights or licence terms', 2, 'that third-party assets are protected by copyright or licence terms', '[{"anyOf":["copyright","licence","licensing","intellectual property","protected"]},{"anyOf":["third party code","third party media","code from someone else","images","audio","assets"]}]'::jsonb),
