insert into public.curriculum_misconceptions (id, topic_id, subtopic_id, question_schema_id, label, explanation, penalty, signal_groups)
values
  ('1.1::abstraction-adds-detail', 'problem-solving', '1.1', 'problem-solving-decomposition-abstraction', 'Abstraction adds extra detail', 'Abstraction removes irrelevant detail. It does not add extra detail to the model.', 1, '[{"anyOf":["abstraction adds detail","abstraction includes every detail"]}]'::jsonb),
  ('1.2::trace-runs-code', 'problem-solving', '1.2', 'problem-solving-trace-tables', 'A trace table automatically runs the code', 'A trace table is a checking method used by a human. It helps simulate the logic, but it does not execute the program by itself.', 1, '[{"anyOf":["trace table runs the code","trace table executes the program"]}]'::jsonb),
  ('2.6::loop-runs-once', 'intro-programming', '2.6', 'intro-programming-validation', 'Iteration only runs once', 'Iteration means repeating a block while a condition still applies. It is not the same as a one-off check.', 1, '[{"anyOf":["loop runs once","iteration happens once"]}]'::jsonb),
  ('2.6::validation-equals-error-handling', 'intro-programming', '2.6', 'intro-programming-validation-error-handling', 'Validation and error handling are the same thing', 'Validation checks whether input should be accepted. Error handling deals with unexpected problems while the program is running. They work together but are not the same.', 1, '[{"anyOf":["validation is the same as error handling","error handling just means validation"]}]'::jsonb),
  ('3.2::ai-no-risk', 'emerging-issues', '3.2', 'emerging-issues-ai', 'AI has no ethical risk', 'AI systems can create ethical issues such as bias, privacy problems, or poor accountability if they are left unchecked.', 1, '[{"anyOf":["ai has no risk","ai is always fair","ai is unbiased by default"]}]'::jsonb),
  ('3.1::biometrics-perfect', 'emerging-issues', '3.1', 'emerging-issues-biometrics', 'Biometrics are always accurate and impossible to misuse', 'Biometric systems can still produce errors, exclude some users, or create privacy concerns if they are poorly chosen or badly managed.', 1, '[{"anyOf":["biometrics are always accurate","biometrics cannot be abused","biometrics are always fair"]}]'::jsonb),
  ('4.1::internal-exemption', 'legislation', '4.1', 'legislation-data-protection', 'Internal storage is exempt from data protection law', 'Data protection responsibilities still apply when a company stores personal data internally or in the cloud.', 1, '[{"anyOf":["internal data does not count","law does not apply inside company"]}]'::jsonb),
  ('4.1::internet-free-to-use', 'legislation', '4.1', 'legislation-copyright-licensing', 'Anything found online is free to use', 'Material being easy to find online does not remove copyright or licensing obligations.', 1, '[{"anyOf":["everything online is free to use","if it is online it is public domain"]}]'::jsonb),
  ('5.3::training-wastes-time', 'business', '5.3', 'business-change-training', 'Training is unnecessary overhead', 'Skipping training usually increases confusion, mistakes, and resistance during a rollout.', 1, '[{"anyOf":["training is a waste of time","users should just figure it out"]}]'::jsonb),
  ('5.3::rollback-no-testing', 'business', '5.3', 'business-change-rollback', 'Rollback planning means the team can skip careful testing', 'Rollback planning is a safety measure. It does not remove the need for proper testing, communication, and controlled release.', 1, '[{"anyOf":["no need to test if you can roll back","rollback replaces testing"]}]'::jsonb),
  ('6.3::foreign-key-unique', 'data', '6.3', 'data-keys-relationships', 'A foreign key must be unique like a primary key', 'A foreign key links related records. It does not need to be unique in the same way as a primary key.', 1, '[{"anyOf":["foreign key is unique","foreign key uniquely identifies every record"]}]'::jsonb),
  ('6.4::backup-fixes-quality', 'data', '6.4', 'data-validation-backups', 'Backups solve poor data quality on their own', 'Backups help recovery after loss, but they do not prevent bad data from entering the system in the first place.', 1, '[{"anyOf":["backup stops invalid data","backups replace validation"]}]'::jsonb),
  ('7.4::cloud-infinite', 'digital-environments', '7.4', 'digital-environments-virtualization-cloud', 'Cloud capacity is automatically infinite', 'Cloud platforms are scalable, but capacity, design, and cost still need to be managed properly.', 1, '[{"anyOf":["cloud is infinite","cloud has unlimited resources for free"]}]'::jsonb),
  ('7.5::same-thing', 'digital-environments', '7.5', 'digital-environments-load-balancing-failover', 'Load balancing and failover are the same thing', 'Load balancing shares work during normal operation. Failover focuses on keeping the service available when a component fails.', 1, '[{"anyOf":["load balancing is failover","they are exactly the same"]}]'::jsonb),
  ('8.2::mfa-replaces-patching', 'security', '8.2', 'security-mfa-patching', 'MFA removes the need for patching', 'MFA protects authentication, but systems still need patching to close software vulnerabilities.', 1, '[{"anyOf":["mfa means patching is unnecessary","patching is not needed if 2fa is enabled"]}]'::jsonb),
  ('8.2::admin-for-everyone', 'security', '8.2', 'security-least-privilege-audit-logs', 'Everyone can have broad access as long as logs exist', 'Audit logs help investigation, but they do not justify giving every user more access than they need.', 1, '[{"anyOf":["everyone can have admin access if it is logged","logs mean broad permissions are safe"]}]'::jsonb),
  ('1.1::pattern-guessing', 'problem-solving', '1.1', 'problem-solving-pattern-recognition', 'Pattern recognition is just guessing', 'Pattern recognition is evidence-based. It looks for meaningful similarities or trends, not random guesses.', 1, '[{"anyOf":["just guess","random guess","guessing without evidence"]}]'::jsonb),
  ('1.2::flowchart-executes', 'problem-solving', '1.2', 'problem-solving-flowcharts-pseudocode', 'A flowchart or pseudocode directly runs as the finished program', 'Flowcharts and pseudocode are planning representations. They help design the solution, but they are not the final executable program.', 1, '[{"anyOf":["flowchart runs the program","pseudocode executes directly","the flowchart is the final code"]}]'::jsonb),
  ('3.1::accessibility-only-small-group', 'emerging-issues', '3.1', 'emerging-issues-digital-inclusion', 'Accessibility only matters for a small group of users', 'Accessibility improves access for many users, not only a small specialist group. It often improves usability more broadly.', 1, '[{"anyOf":["only a few users need accessibility","accessibility only matters for blind users","most users do not need accessible design"]}]'::jsonb),
  ('3.2::iot-no-overheads', 'emerging-issues', '3.2', 'emerging-issues-iot-benefit-risk', 'IoT devices add value without creating extra risk or management work', 'IoT can create new security, privacy, maintenance, and data-quality issues that still need to be managed.', 1, '[{"anyOf":["iot has no risk","iot runs itself","iot does not need managing"]}]'::jsonb),
  ('4.1::employee-can-look', 'legislation', '4.1', 'legislation-computer-misuse-act', 'Employees can access anything inside the company if they are curious', 'Being an employee does not make all access lawful. Staff still need proper authorisation for the systems and data they use.', 1, '[{"anyOf":["employees can access anything","it is allowed if you work there","looking is fine if nothing is changed"]}]'::jsonb),
  ('4.2::codes-irrelevant', 'legislation', '4.2', 'legislation-accessibility-codes', 'Professional codes do not matter because they are not the same as law', 'Professional codes are still important because they guide responsible practice, quality, and ethical decision-making even when they are not laws themselves.', 1, '[{"anyOf":["codes do not matter","ignore codes if not law","professional guidance is optional and useless"]}]'::jsonb),
  ('6.2::json-xml-visual-only', 'data', '6.2', 'data-json-xml-exchange', 'JSON and XML are just visual layout formats', 'JSON and XML are structured data formats used to represent and exchange data, not just to make information look tidy on screen.', 1, '[{"anyOf":["just for display","visual format only","for layout not data"]}]'::jsonb),
  ('6.1::volume-over-speed', 'data', '6.1', 'data-big-data-velocity', 'It is mainly volume just because there is a lot of data', 'There may be a large amount of data, but this scenario mainly emphasises the speed at which data arrives and needs to be handled, which is velocity.', 1, '[{"anyOf":["mainly volume because there is lots of data","the key v is volume not speed"]}]'::jsonb),
  ('6.4::wrangling-only-delete', 'data', '6.4', 'data-wrangling-pipeline', 'Data wrangling only means deleting bad rows', 'Data wrangling is broader than deleting errors. It includes structuring, cleaning, validating, enriching, and preparing data for useful output.', 1, '[{"anyOf":["just delete bad data","only remove rows","wrangling just means deleting errors"]}]'::jsonb),
  ('6.3::hierarchy-fits-all', 'data', '6.3', 'data-network-model-social-media', 'Hierarchical models handle complex many-to-many links just as well', 'Hierarchical models are better for tree-like parent-child structures. Interconnected many-to-many relationships are a stronger fit for a network model.', 1, '[{"anyOf":["hierarchical is just as good for many to many","hierarchy handles any relationship equally well"]}]'::jsonb),
  ('6.3::same-access-for-all', 'data', '6.3', 'data-role-based-access-control', 'Everyone should have the same access so work is faster', 'Giving everyone the same access increases the risk of unauthorised viewing, accidental changes, and misuse. Different roles usually need different permissions.', 1, '[{"anyOf":["everyone should have same access","broad access is best for efficiency","all staff need admin rights"]}]'::jsonb),
  ('6.1::one-chart-fits-all', 'data', '6.1', 'data-visualisation-audience-purpose', 'One chart type works equally well for every audience and purpose', 'Visualisations should be chosen to fit both the intended audience and what the data needs to communicate. One format does not suit every case.', 1, '[{"anyOf":["same chart for everything","one graph suits all","audience does not matter"]}]'::jsonb),
  ('6.3::lake-and-warehouse-same', 'data', '6.3', 'data-warehouse-vs-lake', 'A data lake and a data warehouse are basically the same thing', 'They serve different roles. Warehouses focus on structured, prepared reporting data, while lakes can hold raw and varied data for broader later use.', 1, '[{"anyOf":["same thing","no real difference","warehouse and lake are identical"]}]'::jsonb),
  ('8.1::confidentiality-only-enough', 'security', '8.1', 'security-cia-triad-balance', 'Security is fine as long as data is confidential', 'A system can still fail if data is unavailable or inaccurate, even if unauthorised people cannot see it. Security depends on all three parts of the CIA triad.', 1, '[{"anyOf":["only confidentiality matters","privacy alone is enough","availability does not matter if data is secret"]}]'::jsonb),
  ('8.1::antivirus-solves-phishing', 'security', '8.1', 'security-phishing-human-threat', 'Antivirus alone solves phishing', 'Technical tools help, but phishing is a social-engineering threat that also needs user awareness, good processes, and layered controls.', 1, '[{"anyOf":["antivirus completely stops phishing","only antivirus is needed for phishing"]}]'::jsonb),
  ('8.2::best-single-control-enough', 'security', '8.2', 'security-layered-controls', 'The strongest single control is always enough on its own', 'Even strong controls can fail or be bypassed. Layered security reduces dependence on one point of protection.', 1, '[{"anyOf":["one strong control is enough","best control alone is sufficient","only one security measure is needed"]}]'::jsonb)
